<template><section aria-label="病例去标识共享技术与临床审计"><p>超级管理员技术身份不恢复研究项目、逐患者用途或模型许可。撤回后仅保留技术状态、独立实际用量和不透明SHA。</p><template v-if="allowed&&metadata"><template v-if="metadata.incomplete_native_artifact"><p aria-label="病例去标识缺永久来源技术记录">任务 {{ metadata.run_id }} / {{ metadata.status }}；{{ metadata.error_message }}。</p></template><template v-else><p aria-label="病例去标识技术审计状态">任务 {{ metadata.run_id }}：{{ metadata.status }}。</p><p aria-label="病例去标识技术实际用量">输入 {{ shown(metadata.input_tokens) }}；输出 {{ shown(metadata.output_tokens) }}；{{ metadata.usage_receipt.model_call_attempted===null?'是否调用未知':metadata.usage_receipt.model_call_attempted?'已有实际调用回执':'已确认未调用模型' }}。</p><template v-if="!metadata.clinical_parts_available"><p aria-label="病例去标识技术审计无临床读取">仅技术状态与不透明SHA；没有读取临床Source、Scope、Task、Result或原始问题。</p><pre>{{ JSON.stringify(metadata.opaque_hashes,null,2) }}</pre></template><DeidentificationSharedFindings v-else :run-id="metadata.run_id" :active="active" audit-only @invalidate="emit('invalidate')" @close="emit('close')"/></template></template></section></template>
<script setup>
import{computed}from'vue';import{useStore}from'vuex';import DeidentificationSharedFindings from'./DeidentificationSharedFindings.vue';
const props=defineProps({metadata:{type:Object,required:true},active:{type:Boolean,default:true}}),emit=defineEmits(['invalidate','close']),store=useStore(),allowed=computed(()=>props.active&&!!store.state.user?.accessToken&&Array.isArray(store.state.user?.permissions)&&store.state.user.permissions.includes('super_admin')),shown=v=>v===null?'未知':String(v);
</script>
